            new[] { "Get help, report bugs and find answers.", "Pide ayuda, reporta errores y encuentra respuestas.", "Peça ajuda, relate bugs e encontre respostas." },
            new[] { "Community", "Comunidad", "Comunidade" },
            new[] { "GuideStrap Discord", "Discord de GuideStrap", "Discord do GuideStrap" },
            new[] { "Ask questions, share ideas and hear about updates first.", "Haz preguntas, comparte ideas y entérate primero de las novedades.", "Tire dúvidas, compartilhe ideias e saiba das novidades primeiro." },
            new[] { "Report", "Reportar", "Relatar" },
            new[] { "Report a bug", "Reportar un error", "Relatar um bug" },
            new[] { "Open a ticket in #bug-reports on our Discord. A screenshot helps a lot.", "Abre un ticket en #bug-reports en nuestro Discord. Una captura ayuda mucho.", "Abra um ticket em #bug-reports no nosso Discord. Um print ajuda muito." },
            new[] { "Open", "Abrir", "Abrir" },
            new[] { "Website", "Sitio web", "Site" },
            new[] { "Every feature, downloads and news.", "Todas las funciones, descargas y novedades.", "Todos os recursos, downloads e novidades." },
            new[] { "Common questions", "Preguntas frecuentes", "Perguntas frequentes" },
            new[] { "Can I get banned for using GuideStrap?", "¿Me pueden banear por usar GuideStrap?", "Posso ser banido por usar o GuideStrap?" },
            new[] { "No. It only uses settings from Roblox's own allowlist, which Roblox reads when it starts. It never touches the game while it's running.", "No. Solo usa ajustes de la lista permitida de Roblox, que Roblox lee al iniciar. Nunca toca el juego mientras se ejecuta.", "Não. Ele só usa configurações da lista permitida do próprio Roblox, que o Roblox lê ao iniciar. Ele nunca mexe no jogo enquanto está rodando." },
            new[] { "Does it change my normal Roblox?", "¿Cambia mi Roblox normal?", "Ele muda meu Roblox normal?" },
            new[] { "No. GuideStrap uses its own copy of Roblox, so normal Roblox stays exactly as it is.", "No. GuideStrap usa su propia copia de Roblox, así que tu Roblox normal queda tal cual.", "Não. O GuideStrap usa a própria cópia do Roblox, então o Roblox normal fica do jeito que está." },
            new[] { "My changes don't show in game", "Mis cambios no se ven en el juego", "Minhas mudanças não aparecem no jogo" },
            new[] { "Close Roblox fully, then launch it again from GuideStrap. Changes apply when Roblox starts.", "Cierra Roblox por completo y vuelve a abrirlo desde GuideStrap. Los cambios se aplican cuando Roblox inicia.", "Feche o Roblox por completo e abra de novo pelo GuideStrap. As mudanças valem quando o Roblox inicia." },
            new[] { "Roblox won't open or keeps crashing", "Roblox no abre o se sigue cerrando", "O Roblox não abre ou fica crashando" },
            new[] { "Try Settings > Tools > Repair Roblox. If it still crashes, the crash helper shows what went wrong and how to fix it.", "Prueba Ajustes > Herramientas > Reparar Roblox. Si sigue fallando, la Ayuda con cierres te muestra qué pasó y cómo arreglarlo.", "Tente Configurações > Ferramentas > Reparar Roblox. Se ainda crashar, a Ajuda com travamentos mostra o que deu errado e como resolver." },
            new[] { "How do I uninstall?", "¿Cómo lo desinstalo?", "Como desinstalo?" },
            new[] { "Settings > Tools > Uninstall GuideStrap, or from Windows' Installed apps list.", "Ajustes > Herramientas > Desinstalar GuideStrap, o desde la lista de aplicaciones instaladas de Windows.", "Configurações > Ferramentas > Desinstalar o GuideStrap, ou pela lista de aplicativos instalados do Windows." },
