            new[] { "Processor: {0} threads", "Processeur : {0} threads", "Prozessor: {0} Threads", "İşlemci: {0} iş parçacığı", "Processor: {0} thread" },
            new[] { "Screen: {0} Hz", "Écran : {0} Hz", "Bildschirm: {0} Hz", "Ekran: {0} Hz", "Screen: {0} Hz" },
            new[] { "Recommended graphics: {0}", "Graphismes recommandés : {0}", "Empfohlene Grafik: {0}", "Önerilen grafik: {0}", "Inirerekomendang graphics: {0}" },
            new[] { "Recommended FPS cap: {0}", "Limite de FPS recommandée : {0}", "Empfohlenes FPS-Limit: {0}", "Önerilen FPS sınırı: {0}", "Inirerekomendang FPS cap: {0}" },
            new[] { "This only changes your graphics settings and FPS cap. Your mods, accounts and other settings stay the same.", "Ceci change seulement tes réglages graphiques et la limite de FPS. Tes mods, comptes et autres réglages restent pareils.", "Das ändert nur deine Grafikeinstellungen und das FPS-Limit. Deine Mods, Konten und anderen Einstellungen bleiben gleich.", "Bu sadece grafik ayarlarını ve FPS sınırını değiştirir. Modların, hesapların ve diğer ayarların aynı kalır.", "Graphics settings at FPS cap mo lang ang binabago nito. Pareho pa rin ang mods, account at ibang settings mo." },
            new[] { "Use recommended settings for your PC?", "Utiliser les réglages recommandés pour ton PC ?", "Empfohlene Einstellungen für deinen PC nutzen?", "Bilgisayarın için önerilen ayarlar kullanılsın mı?", "Gamitin ang inirerekomendang settings para sa PC mo?" },
            new[] { "Recommended settings for your PC", "Réglages recommandés pour ton PC", "Empfohlene Einstellungen für deinen PC", "Bilgisayarın için önerilen ayarlar", "Inirerekomendang settings para sa PC mo" },
            new[] { "Use recommended", "Utiliser les recommandés", "Empfohlene nutzen", "Önerilenleri kullan", "Gamitin ang inirerekomenda" },
            new[] { "Keep mine", "Garder les miens", "Meine behalten", "Benimkileri koru", "Panatilihin ang akin" },
            new[] { "Recommended settings loaded: {0} graphics.", "Réglages recommandés chargés : graphismes {0}.", "Empfohlene Einstellungen geladen: Grafik {0}.", "Önerilen ayarlar yüklendi: {0} grafik.", "Na-load ang inirerekomendang settings: {0} na graphics." },
            new[] { "• GuideStrap can check your PC and recommend graphics settings (Graphics > Recommended)\n• Long descriptions no longer run under buttons and dropdowns\n• GuideStrap now steps aside while you play, so Roblox and your PC stay smooth\n• Set your FPS cap to any number you want (Graphics > FPS cap)", "• GuideStrap peut analyser ton PC et te recommander des réglages graphiques (Graphismes > Recommandé)\n• Les longues descriptions ne passent plus sous les boutons et les listes\n• GuideStrap se met maintenant en retrait pendant que tu joues, pour que Roblox et ton PC restent fluides\n• Règle la limite de FPS que tu veux (Graphismes > Limite de FPS)", "• GuideStrap kann deinen PC prüfen und Grafikeinstellungen empfehlen (Grafik > Empfohlen)\n• Lange Beschreibungen laufen nicht mehr unter Buttons und Auswahllisten\n• GuideStrap hält sich jetzt beim Spielen zurück, damit Roblox und dein PC flüssig bleiben\n• Setz dein FPS-Limit auf jede beliebige Zahl (Grafik > FPS-Limit)", "• GuideStrap bilgisayarını kontrol edip grafik ayarları önerebilir (Grafikler > Önerilen)\n• Uzun açıklamalar artık düğmelerin ve menülerin altına girmiyor\n• GuideStrap artık sen oynarken geri planda kalıyor, böylece Roblox ve bilgisayarın akıcı kalıyor\n• FPS sınırını istediğin sayıya ayarla (Grafikler > FPS sınırı)", "• Kaya nang tingnan ng GuideStrap ang PC mo at magrekomenda ng graphics settings (Graphics > Inirerekomenda)\n• Hindi na tumatama sa mga button at dropdown ang mahahabang paliwanag\n• Umaatras na ang GuideStrap habang naglalaro ka, para smooth ang Roblox at PC mo\n• I-set ang FPS cap sa kahit anong numero (Graphics > FPS cap)" },
